class FrequencyUnits(object):
    """ Names and multipliers of supported frequency units """

    Hz = 'hz'
    kHz = 'khz'
    MHz = 'mhz'
    GHz = 'ghz'

    multipliers = {
        Hz: 1,
        kHz: 1000.0,
        MHz: 1000000.0,
        GHz: 1000000000.0
    }
